texts={}; log=[]; bad=0
for f,o,n,cnt in E:
    p=os.path.join(D,f+'.vi.md')
    t=texts.get(p) or open(p,encoding='utf-8').read()
    k=t.count(o)
    if k!=cnt: print('MISMATCH',f,k,'!=',cnt,o[:70]); bad+=1; continue
    if o==n: continue
    # line numbers before
    lines=[i+1 for i,l in enumerate(t.split('\n')) if o in l]
    t=t.replace(o,n); texts[p]=t
    log.append((f,lines,o,n))
if bad and '--force' not in sys.argv: print('aborting'); sys.exit(1)
for p,t in texts.items(): open(p,'w',encoding='utf-8').write(t)
json.dump(log,open(os.path.join(os.path.dirname(__file__),'edits.json'),'w'),ensure_ascii=False,indent=0)
print('applied',len(log),'edits in',len(texts),'files')
